  connectionName: ConnectionName,
): Promise<string[]> {
  const names = new Set<string>();
  let pageToken: string | undefined;

  do {
    const response = await scalekit.tools.listScopedTools(connectionName, USER_ID, {
      pageSize: PAGE_SIZE,
      ...(pageToken ? { pageToken } : {}),
    });

    for (const scopedTool of extractTools(response)) {
      const name = scopedTool.tool?.definition?.name;
      if (typeof name === "string" && name.length > 0) {
        names.add(name);
      }
    }

    pageToken = extractNextPageToken(response);
  } while (pageToken);

  return [...names].sort();
}

